  "liveDiag.clearBody": "라이브 송출 로그를 모두 삭제합니다. 고객지원에 신고한 후 사용하세요.",
  "liveDiag.whatTitle": "이게 뭔가요?",
  "liveDiag.whatBody": "라이브를 시작하면 앱이 카메라와 마이크를 방송 서버로 보내고, 서버가 시청자에게 영상을 전달합니다. 이 과정에서 문제가 생기면(네트워크, 권한, NAT) 시청자는 \"연결 중…\"에서 멈춥니다. 마지막 송출 기록이 여기에 남아 있어 어디서 멈췄는지 직접(또는 고객지원이) 확인할 수 있어요.",
