  "liveDiag.empty": "아직 기록이 없어요. 라이브를 시작해 방송해 본 뒤 여기로 돌아와 결과를 확인하세요.",
  "liveDiag.okSummary": "마지막 방송이 정상적으로 송출되었어요.",
  "liveDiag.iceNat": "네트워크 차단(ICE/NAT): 휴대폰이 방송 서버에 연결하지 못했어요. 대칭형 NAT 뒤의 4G/5G에서 흔해요. Wi‑Fi로 시도해 보세요.",
  "liveDiag.iceTimeout": "연결(ICE)이 20초 안에 완료되지 않았어요. 방화벽이나 회사 네트워크가 차단하고 있을 수 있어요. 다른 네트워크로 시도해 보세요.",
  "liveDiag.inactive": "서버가 송출 방향을 거부했어요(sendrecv → inactive). 이 메시지가 보이면 고객지원에 문의하세요.",
  "liveDiag.whip4xx": "서버가 미디어 요청을 거부했어요(4xx). 라이브를 종료하고 다시 시작하세요. 계속되면 코덱이나 인증서 호환 문제예요.",
  "liveDiag.noTracks": "카메라 또는 마이크를 사용할 수 없어요. 설정 > Chatyy에서 권한을 확인하세요.",
